import{_ as t,o as r,c as s,j as e,a as i}from"./chunks/framework.UjrY2eRK.js";const m=JSON.parse('{"title":"Operate self-hosted state as local durable SQLite","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0016-operate-self-hosted-state-as-local-durable-sqlite.md","filePath":"architecture/adr/0016-operate-self-hosted-state-as-local-durable-sqlite.md","lastUpdated":1788123021000}'),o={name:"architecture/adr/0016-operate-self-hosted-state-as-local-durable-sqlite.md"};function l(n,a,d,c,u,p){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"operate-self-hosted-state-as-local-durable-sqlite",tabindex:"-1"},[i("Operate self-hosted state as local durable SQLite "),e("a",{class:"header-anchor",href:"#operate-self-hosted-state-as-local-durable-sqlite","aria-label":'Permalink to "Operate self-hosted state as local durable SQLite"'},"​")],-1),e("p",null,"The Bun deployment will keep delivery coordination and daily budgets in one local SQLite database owned by one service process. It will use strict bindings, WAL mode, full synchronous durability, foreign keys, and a finite busy timeout; forward-only migrations run before the HTTP listener opens, while expired-state cleanup runs at startup and every 24 hours. The short source-IP limit remains in memory because it is best-effort and persisting every public request would turn SQLite into an avoidable contention surface.",-1),e("p",null,"The database and its WAL files must remain together on a local persistent volume. The gateway will include a consistent online backup command plus cold-backup and integrity-check instructions, but not remote backup storage or scheduling. A network filesystem, multiple gateway replicas sharing one file, destructive automatic migration, or serving with an unknown schema version is unsupported.",-1),e("p",null,"Schema changes must be expand-first and readable by the immediately preceding stable image so operators retain a one-version rollback path. Busy, full, I/O, and corruption failures remain explicit retryable gateway failures rather than bypassing coordination or budgets; migration, incompatible-schema, and startup integrity failures terminate the process. Configuration and credential files are read once at startup and require a controlled container recreation to change.",-1)])])}const b=t(o,[["render",l]]);export{m as __pageData,b as default};
